const BATTLE_IMAGE_FOCAL={"1-jinxed-broom-1.jpg":"72% 48%","1-potions-2.jpg":"46% 33%","3-quidditch-dementors-2.jpg":"66% 30%","3-rescue-1.jpg":"52% 58%","4-dragon-2.jpg":"39% 58%","4-graveyard-2.jpg":"44% 35%","4-maze-5.jpg":"54% 33%","5-death-chamber-3.jpg":"66% 30%","5-privet-dementors-1.jpg":"71% 47%","6-flight-prince-2.jpg":"45% 43%","6-hogwarts-invasion-1.jpg":"54% 31%","6-horcrux-cave-1.jpg":"52% 35%","7-fiendfyre-1.jpg":"36% 43%","7-malfoy-manor-2.jpg":"45% 31%","7-tottenham-2.jpg":"39% 30%","7-xenophilius-1.jpg":"75% 58%","1-remembrall-2.jpg":"32% 25%","1-quirrell-2.jpg":"25% 42%","7-return-hogwarts-2.jpg":"44% 34%","7-battle-hogwarts-2.jpg":"48% 34%","7-tottenham-1.jpg":"50% 34%"};
function encounterArtwork(enc,stage=0){
  const imgs=BATTLE_IMAGES[`${enc.book}-${enc.id}`]||[];
  if(!imgs.length)return `<span>${enc.art}</span>`;
  const src=imgs[Math.max(0,Number(stage)||0)%imgs.length];
  const file=src.split('/').pop();
  const focal=BATTLE_IMAGE_FOCAL[file]||'50% 45%';
  const specialClass=file==='1-remembrall-2.jpg'?'battle-remembrall':'';
  return `<img class="${specialClass}" src="${src}" alt="" loading="eager" decoding="async" style="--battle-focal:${focal}" onerror="this.style.display='none';this.parentElement.classList.add('art-failed')"><span class="art-fallback">${enc.art}</span>`;
};
function retryTrialFor(fails){
  const tier=Math.min(2,Math.max(0,fails-1));
  const pick=RETRY_TRIALS[Math.floor(Math.random()*RETRY_TRIALS.length)];
  return {...pick,amount:pick.amounts[tier]};
}
function sagaState(){
  if(!save.adventure65)save.adventure65={encounterIndex:0,stage:0,lastResult:null,retry:{fails:0,locked:false,trial:null},rewards:{}};
  const s=save.adventure65;
  if(!s.retry)s.retry={fails:0,locked:false,trial:null};
  if(!s.rewards)s.rewards={};
  s.encounterIndex=Math.max(0,Math.min(Number(s.encounterIndex)||0,SAGA_ENCOUNTERS.length-1));
  return s;
}
function encounterThreshold(level){return cumulativeXpForLevel(level);}
function encounterStartThreshold(enc){return cumulativeXpForLevel(enc.prevLevel);}
function encounterXp(enc){
  const start=encounterStartThreshold(enc),target=encounterThreshold(enc.level),span=Math.max(1,target-start);
  return {earned:Math.max(0,Math.min(span,save.totalXP-start)),target:span,ready:save.totalXP>=target};
}
function adventureBook(){return SAGA_ENCOUNTERS[sagaState().encounterIndex]?.book||1;}
function adventureState(){return sagaState();}
function sceneXp(enc){return encounterXp(enc);}
function stagePrompt(enc,stage){
  const n=stage+1,total=enc.stages;
  const intros=[
    `${enc.title} has shifted into a dangerous new phase. Harry has seconds to read what is happening before committing.`,
    `The obvious route is no longer obviously safe. What Harry has learned so far matters more than raw confidence.`,
    `Pressure rises. Harry must decide what matters most right now rather than simply choosing the most powerful action.`,
    `The situation changes again. An earlier lesson, ally or ability may be more useful than it first appears.`,
    `There is little margin left for error. Harry needs to act on the information actually available to him.`,
    `The confrontation reaches its decisive phase. Every earlier choice has brought Harry to this point.`,
    `Only the final decision remains. Harry has to understand the enemy, not merely overpower him.`
  ];
  return `${intros[Math.min(stage,intros.length-1)]} Stage ${n} of ${total}.`;
}
function stageQuestion(enc,stage){
  if(enc.kind==='cinematic') return 'How does the moment unfold around Harry?';
  if(enc.kind==='trial') return 'What must Harry understand or choose to continue?';
  if(enc.kind==='final') return stage===enc.stages-1?'What finally decides the confrontation?':'What does Harry do next?';
  return stage%3===0?'What does Harry do?':stage%3===1?'Which approach gives Harry the best chance?':'What matters most in this moment?';
}
function stageChoices(enc,stage){
  // Fixed per-stage rotation keeps answers deterministic while hiding them from the player.
  const cats=['knowledge','combat','assets','magic'];
  const correct=(enc.level+stage*3)%3;
  const labels=[
    ['Read the situation first','Commit to the direct approach','Use what the journey has already given Harry'],
    ['Control the immediate threat','Force the quickest route','Trust the strongest available advantage'],
    ['Act on what Harry knows now','Overpower the obstacle','Use an ally, tool or earlier lesson']
  ][stage%3];
  const outcomes=[
    `Harry notices the detail that changes the encounter. The path forward opens.`,
    `Harry commits too early. The threat turns that impatience against him.`,
    `Something earned earlier in the journey becomes useful at exactly the right moment.`
  ];
  return labels.map((label,i)=>{
    const good=i===correct;
    return {
      icon:CAT_META[cats[(i+stage)%cats.length]].icon,
      cat:cats[(i+stage)%cats.length],
      rank:Math.min(5,Math.max(1,Math.ceil(enc.book/2)+(stage>2?1:0))),
      label,
      outcome:good?outcomes[i]:`The choice is plausible, but Harry has missed something important. ${enc.title} turns against him and he must regroup before trying this stage again.`,
      advance:good
    };
  });
}
function grantEncounterRewards(enc,state){
  if(state.rewards[enc.id])return;
  state.rewards[enc.id]=enc.rewards.slice();
  if(!save.harryState)save.harryState={skills:[],knowledge:[],allies:[],arsenal:[]};
  for(const r of enc.rewards){
    const lower=r.toLowerCase();
    const bucket=/ally|ron|hermione|sirius|fawkes|dobby|neville/.test(lower)?'allies':
      /sword|wand|broom/.test(lower)?'arsenal':
      /knowledge|truth|weakness|prophecy|horcrux|hallows|connection|mystery|diary|venom/.test(lower)?'knowledge':'skills';
    if(!save.harryState[bucket].includes(r))save.harryState[bucket].push(r);
  }
}
function advanceEncounter(state,enc){
  grantEncounterRewards(enc,state);
  state.stage=0;state.lastResult=null;state.retry={fails:0,locked:false,trial:null};
  if(state.encounterIndex<SAGA_ENCOUNTERS.length-1)state.encounterIndex++;
  else state.sagaComplete=true;
}
function renderBattle(){
  const hub=document.querySelector('#battleHub');if(!hub)return;
  const state=sagaState(),enc=SAGA_ENCOUNTERS[state.encounterIndex],retry=state.retry,xp=encounterXp(enc);

  if(state.sagaComplete){
    hub.innerHTML=`<section class="adv60 adv60-result"><span>THE STORY IS COMPLETE</span><h2>⚡ Harry vs Voldemort</h2><p>Seven years of training, knowledge, allies and choices have converged. Harry has survived the final confrontation.</p></section>`;
    return;
  }

  if(retry.locked&&retry.trial){
    const t=retry.trial;
    hub.innerHTML=`<section class="adv60 adv63-retry">
      <span class="adv63-kicker">ATTEMPT FAILED</span><div class="adv63-retry-icon">${t.icon}</div>
      <h2>Retry Trial</h2>
      <p>Harry needs to regroup before returning to <strong>${enc.title}</strong>.</p>
      <div class="adv63-task"><b>${t.amount}${t.unit}</b><span>${t.label}</span></div>
      <small>No XP awarded. This challenge only earns another attempt.</small>
      <button class="primary wide" id="completeRetry">Complete Retry Trial</button>
    </section>`;
    hub.querySelector('#completeRetry').onclick=()=>{retry.locked=false;retry.trial=null;persist();renderBattle();window.scrollTo({top:0,behavior:'smooth'});};
    return;
  }

  if(state.lastResult){
    const r=state.lastResult;
    hub.innerHTML=`<section class="adv60 adv60-result"><span>${r.success?'SUCCESS':'FAILED ATTEMPT'}</span><h2>${r.label}</h2><p>${r.outcome}</p>
      <button class="primary wide" id="advContinue">${r.success?'Continue':'Face the consequence'}</button></section>`;
    hub.querySelector('#advContinue').onclick=()=>{
      if(r.success){
        state.lastResult=null;retry.fails=0;retry.locked=false;retry.trial=null;
        if(state.stage<enc.stages-1)state.stage++; else advanceEncounter(state,enc);
      }else{
        retry.fails=(retry.fails||0)+1;retry.trial=retryTrialFor(retry.fails);retry.locked=true;state.lastResult=null;
      }
      persist();render();window.scrollTo({top:0,behavior:'smooth'});
    };
    return;
  }

  if(!xp.ready){
    hub.innerHTML=`<section class="adv60 adv65-locked">
      <div class="adv60-top"><div><span>UPCOMING ENCOUNTER</span><h2>${enc.art} ${enc.title}</h2></div></div>
      <div class="adv60-atmosphere">${encounterArtwork(enc,0)}</div>
      <p class="adv60-story">Harry is not ready to enter this encounter yet. Complete your normal missions to build the XP required for the next battle.</p>
      <div class="adv65-xp"><b>${xp.earned.toLocaleString()} / ${xp.target.toLocaleString()} XP</b><i><u style="width:${Math.round(xp.earned/xp.target*100)}%"></u></i></div>
    </section>`;
    return;
  }

  if(enc.kind==='cinematic'){
    hub.innerHTML=`<section class="adv60 adv60-result"><span>ALLY PAYOFF</span><h2>${enc.art} ${enc.title}</h2>
      <p>This moment belongs to an ally whose journey has been developing alongside Harry's. Harry's earlier choices have helped create the conditions for it.</p>
      <button class="primary wide" id="cinematicContinue">Witness the moment</button></section>`;
    hub.querySelector('#cinematicContinue').onclick=()=>{advanceEncounter(state,enc);persist();render();};
    return;
  }

  const choices=stageChoices(enc,state.stage);
  hub.innerHTML=`<section class="adv60">
    <div class="adv60-top"><div><span>BOOK ${enc.book} • ${enc.kind==='final'?'FINAL BOSS':enc.kind==='trial'?'SPECIAL TRIAL':'BATTLE'}</span><h2>${enc.title}</h2></div><small>${state.stage+1}/${enc.stages}</small></div>
    <div class="adv60-atmosphere">${encounterArtwork(enc,state.stage)}</div>
    <p class="adv60-story">${stagePrompt(enc,state.stage)}</p>
    <h3>${stageQuestion(enc,state.stage)}</h3>
    <div class="adv60-choices">${choices.map((c,i)=>{
      const rank=readinessRank(c.cat),available=rank>=c.rank;
      return `<button class="${available?'available':'locked'}" data-choice="${i}" ${available?'':'disabled'}><span>${c.icon}</span><div><b>${c.label}</b><small>${available?'CHOOSE':`${CAT_META[c.cat].name} ${c.rank} NEEDED • ${rank} NOW`}</small></div></button>`;
    }).join('')}</div>
    ${retry.fails?`<p class="adv63-attempt">Failed attempts this battle: ${retry.fails}</p>`:''}
  </section>`;
  hub.querySelectorAll('.adv60-choices button.available').forEach(btn=>btn.onclick=()=>{
    const c=choices[Number(btn.dataset.choice)];
    state.lastResult={label:c.label,outcome:c.outcome,success:!!c.advance};
    persist();renderBattle();window.scrollTo({top:0,behavior:'smooth'});
  });
}

function renderStats(){
  const root=document.querySelector('#statsDashboard'); if(!root)return;

  const today=new Date();
  const dailyHabits=(DATA.habits?.dailyHabits||[]).filter(h=>h.input!=='sleep');
  const habitCount=dailyHabits.length||1;

  // ---- 7-day average sleep + 7-day completion chart ----
  let sleepTotal=0,sleepDays=0;
  const dailyBars=[];
  for(let offset=6;offset>=0;offset--){
    const d=addDays(today,-offset),key=localDateKey(d),day=save.daily?.[key];
    const done=day?dailyHabits.filter(h=>day.habits?.[h.id]?.completed).length:0;
    const pct=Math.round((done/habitCount)*100);
    const label=d.toLocaleDateString(undefined,{weekday:'short'}).slice(0,2);
    dailyBars.push({label,pct,done,total:habitCount});

    const s=day?.sleep;
    const totalSleep=s?.totalHours??((s?.mainHours||0)+(s?.napHours||0));
    if(totalSleep>0){sleepTotal+=totalSleep;sleepDays++;}
  }
  const avgSleep7=sleepDays?sleepTotal/sleepDays:0;

  // ---- current month completed daily habits ----
  const monthPrefix=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-`;
  const habitsMonth=Object.entries(save.daily||{}).reduce((n,[key,day])=>{
    if(!key.startsWith(monthPrefix)) return n;
    return n+dailyHabits.filter(h=>day.habits?.[h.id]?.completed).length;
  },0);

  // ---- lifetime physical / study / recovery history ----
  let gym=0,cardio=0,sport=0,sauna=0,screenCycle=0;
  for(const w of Object.values(save.weekly||{})){
    gym+=Number(w?.weights||0);
    cardio+=Number(w?.cardio||0);
    sport+=Number(w?.sportActual||0);
    sauna+=Number(w?.sauna||0);
    screenCycle+=Number(w?.screenCycle||0);
  }
  const steps7000=Object.values(save.daily||{}).reduce((n,day)=>n+(day?.habits?.steps7000?.completed?1:0),0);
  const study=Object.values(save.daily||{}).reduce((n,day)=>n+(day?.habits?.readStudy?.completed?1:0),0);
  const hindiSpeaking=Object.values(save.daily||{}).reduce((n,day)=>n+(day?.habits?.hindiSpeaking?.completed?1:0),0);

  // ---- lifetime nutrition history ----
  const nutritionIds=[
    ['proteinCreatine','🥤','Protein'],
    ['supplements','💊','Supplements'],
    ['fruit','🍎','Fruit'],
    ['healthyLunch','🥗','Lunch'],
    ['healthyDinner','🍲','Dinner'],
    ['water','💧','Water']
  ];
  const nutrition=nutritionIds.map(([id,icon,label])=>{
    const count=Object.values(save.daily||{}).reduce((n,day)=>n+(day?.habits?.[id]?.completed?1:0),0);
    return {id,icon,label,count};
  });

  root.innerHTML=`<section class="stats62">
    <div class="stats62-summary">
      <div><span>7-day avg sleep</span><strong>${avgSleep7?avgSleep7.toFixed(1)+'h':'—'}</strong></div>
      <div><span>Habits this month</span><strong>${habitsMonth}</strong></div>
    </div>

    <section class="stats62-card">
      <span class="eyebrow">TRAINING HISTORY</span>
      <div class="stats62-history">
        <div><span>🏋️</span><b>${gym}</b><small>Gym</small></div>
        <div><span>🏃</span><b>${cardio}</b><small>Cardio</small></div>
        <div><span>🚶</span><b>${steps7000}</b><small>7,000 Steps</small></div>
        <div><span>⚽</span><b>${sport}</b><small>Sport</small></div>
        <div><span>📚</span><b>${study}</b><small>Study</small></div>
        <div><span>🗣️</span><b>${hindiSpeaking}</b><small>Hindi</small></div>
        <div><span>🧖</span><b>${sauna}</b><small>Sauna</small></div>
        <div><span>🚴</span><b>${screenCycle}</b><small>Screen Cycle</small></div>
      </div>
    </section>

    <section class="stats62-card">
      <span class="eyebrow">NUTRITION HISTORY</span>
      <div class="stats62-history">
        ${nutrition.map(x=>`<div><span>${x.icon}</span><b>${x.count}</b><small>${x.label}</small></div>`).join('')}
      </div>
    </section>

    <section class="stats62-card">
      <span class="eyebrow">LAST 7 DAYS</span>
      <div class="stats62-chart">
        ${dailyBars.map(x=>`<div>
          <b>${x.pct}%</b>
          <em>${x.done}/${x.total}</em>
          <i><u style="height:${Math.max(4,x.pct)}%"></u></i>
          <small>${x.label}</small>
        </div>`).join('')}
      </div>
      <p class="stats62-note">Daily mission completion</p>
    </section>
  </section>`;
}





