function renderSettings(){const standalone=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone;document.querySelector('#installState').textContent=standalone?'Installed and running from your Home Screen in standalone mode.':'Browser mode: use Safari → Share → Add to Home Screen.';document.querySelector('#soundToggle').textContent=save.soundEnabled?'On':'Off';document.querySelector('#soundToggle').classList.toggle('off',!save.soundEnabled);document.querySelector('#devTools').hidden=!DEV_MODE;}
function render(){renderHome();renderBattle();renderStats();}
function escapeHtml(s){return String(s??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[m]));}

function setupUI(){
  document.querySelectorAll('.bottom-nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.bottom-nav button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${b.dataset.view}`));if(b.dataset.view==='battle')renderBattle();if(b.dataset.view==='stats')renderStats();window.scrollTo({top:0,behavior:'smooth'});});
  document.querySelector('#saveSleep').onclick=saveSleep;document.querySelector('#sleepHours').oninput=renderSleep;document.querySelector('#napHours').oninput=renderSleep;document.querySelector('#napHours').oninput=renderSleep;
  document.querySelector('#revealNext').onclick=()=>closeReveal(false);document.querySelector('#revealSkip').onclick=()=>closeReveal(true);
  const soundToggle=document.querySelector('#soundToggle');if(soundToggle)soundToggle.onclick=()=>{save.soundEnabled=!save.soundEnabled;persist();if(save.soundEnabled)playChime('success');};
  document.querySelector('#exportSave').onclick=()=>{
    // Human-readable Excel-friendly habit diary: one row per logged date.
    const habits=(DATA.habits?.dailyHabits||[]).filter(h=>h.input!=='sleep');
    const header=['Date',...habits.map(h=>h.name),'Screen Time Cycling (5-min intervals)','Main Sleep (hours)','Nap (hours)'];
    const rows=[header];
    const cyclingByDate={};
    for(const week of Object.values(save.weekly||{})){
      for(const item of (week?.screenCycleLog||[])){
        if(!item?.date)continue;
        cyclingByDate[item.date]=(cyclingByDate[item.date]||0)+Math.max(1,Number(item.intervals||1));
      }
    }
    const dates=new Set([...Object.keys(save.daily||{}),...Object.keys(cyclingByDate)]);
    for(const date of [...dates].sort()){
      const day=save.daily[date]||{};
      const vals=habits.map(h=>day.habits?.[h.id]?.completed?'Y':'N');
      rows.push([date,...vals,cyclingByDate[date]||0,day.sleep?.mainHours??'',day.sleep?.napHours??'']);
    }
    const q=v=>`"${String(v??'').replace(/"/g,'""')}"`;
    const csv='\uFEFF'+rows.map(r=>r.map(q).join(',')).join('\r\n');
    const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');
    a.href=URL.createObjectURL(blob);a.download=`accio-habits-habit-log-${localDateKey()}.csv`;a.click();URL.revokeObjectURL(a.href);
  };
  document.querySelector('#importSave').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const txt=await f.text();const raw=JSON.parse(txt);save=mergeState(raw);persist();ensureCurrentWeek();finalizePastDays();render();toast('Save imported.');}catch{toast('That save file could not be read.','warn');}};
  if(DEV_MODE){document.querySelectorAll('[data-xp]').forEach(b=>b.onclick=()=>addXP(Number(b.dataset.xp),'Development tester'));document.querySelector('#resetSave').onclick=()=>{if(confirm('Reset TEST progress on this device?')){localStorage.removeItem(stateKey);save=defaultState();ensureCurrentWeek();persist();render();}};}
}
